protected void startArray(String name) {
  JsonValue value = new JsonValue(ValueType.array);
  if (current != null) {
    try {
      addChild(name, value);
    } catch (RuntimeException | IndexOutOfBoundsException | NullPointerException e) {
      // Handle or log the exception
      e.printStackTrace();
    }
  }
  elements.add(value);
  current = value;
}
